import {
  sqliteTable,
  text,
  integer,
  index,
  uniqueIndex,
} from "drizzle-orm/sqlite-core";
import { sql, relations } from "drizzle-orm";
import type {
  CalendarViewSettings,
  PersonalViewSettings,
} from "../view-settings";
import type { Capability } from "../permission-bundles";
import type { CustomFieldOption, CustomFieldType } from "../custom-fields";

// =====================================================
// Better Auth Tables (generated by @better-auth/cli)
// =====================================================

export const user = sqliteTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: integer("email_verified", { mode: "boolean" })
    .default(false)
    .notNull(),
  image: text("image"),
  createdAt: integer("created_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull(),
  updatedAt: integer("updated_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .$onUpdate(() => new Date())
    .notNull(),
  // Better Auth Admin Plugin fields
  role: text("role"),
  banned: integer("banned", { mode: "boolean" }).default(false),
  banReason: text("ban_reason"),
  banExpires: integer("ban_expires", { mode: "timestamp_ms" }),
  // Set on admin-created accounts; cleared once the user changes their password
  mustChangePassword: integer("must_change_password", { mode: "boolean" })
    .notNull()
    .default(false),
});

export const session = sqliteTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
    token: text("token").notNull().unique(),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    // Better Auth Admin Plugin field
    impersonatedBy: text("impersonated_by"),
  },
  (table) => [index("session_userId_idx").on(table.userId)]
);

export const account = sqliteTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: integer("access_token_expires_at", {
      mode: "timestamp_ms",
    }),
    refreshTokenExpiresAt: integer("refresh_token_expires_at", {
      mode: "timestamp_ms",
    }),
    scope: text("scope"),
    password: text("password"),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("account_userId_idx").on(table.userId)]
);

export const verification = sqliteTable("verification", {
  id: text("id").primaryKey(),
  identifier: text("identifier").notNull(),
  value: text("value").notNull(),
  expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
  createdAt: integer("created_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull(),
  updatedAt: integer("updated_at", { mode: "timestamp_ms" }).$onUpdate(
    () => new Date()
  ),
});

// =====================================================
// BetterShift Application Tables
// =====================================================

export const calendars = sqliteTable(
  "calendars",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    name: text("name").notNull(),
    color: text("color").notNull().default("#3b82f6"),
    ownerId: text("owner_id").references(() => user.id, {
      onDelete: "set null",
    }),
    // Bundle granted to guests/subscribed users via the public-access link;
    // null = no guest access (replaces the old guestPermission enum below).
    // Not a typed FK — calendarPermissionBundles.calendarId already points
    // back at this table, and Drizzle/TS can't infer a two-table reference
    // cycle. Bundles can't be deleted while assigned (enforced at the app
    // layer), so integrity holds without a DB-level constraint here.
    guestBundleId: text("guest_bundle_id"),
    // Master switch for the whole shift-signup feature on this calendar.
    // Owner/admin only; off hides capacity, signup lists and badges everywhere.
    signupsEnabled: integer("signups_enabled", { mode: "boolean" })
      .notNull()
      .default(true),
    // Master switch for split shifts (multiple time ranges per shift/preset)
    // on this calendar. Owner/admin only; off hides extra ranges everywhere,
    // same contract as signupsEnabled above.
    splitShiftsEnabled: integer("split_shifts_enabled", { mode: "boolean" })
      .notNull()
      .default(false),
    // null = no own view; every user sees their personal view
    viewSettings: text("view_settings", {
      mode: "json",
    }).$type<CalendarViewSettings>(),
    createdAt: integer("created_at", { mode: "timestamp" })
      .notNull()
      .default(sql`CURRENT_TIMESTAMP`),
    updatedAt: integer("updated_at", { mode: "timestamp" })
      .notNull()
      .default(sql`CURRENT_TIMESTAMP`),
  },
  (table) => [index("calendars_ownerId_idx").on(table.ownerId)]
);

// Owner-defined, per-calendar capability bundle. Replaces the old fixed
// read/write/admin ladder — see lib/permission-bundles.ts for the catalog.
export const calendarPermissionBundles = sqliteTable(
  "calendar_permission_bundles",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    calendarId: text("calendar_id")
      .notNull()
      .references(() => calendars.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    // Set for the four seeded bundles (read/contribute/manage/admin), null
    // once renamed. While set, the UI shows the translated standard name
    // instead of `name` (which stays as an English fallback).
    seedKey: text("seed_key", {
      enum: ["read", "contribute", "manage", "admin"],
    }),
    capabilities: text("capabilities", { mode: "json" })
      .$type<Capability[]>()
      .notNull(),
    createdAt: integer("created_at", { mode: "timestamp" })
      .notNull()
      .default(sql`CURRENT_TIMESTAMP`),
    updatedAt: integer("updated_at", { mode: "timestamp" })
      .notNull()
      .default(sql`CURRENT_TIMESTAMP`)
      .$onUpdate(() => new Date()),
  },
  (table) => [
    index("calendar_permission_bundles_calendarId_idx").on(table.calendarId),
    uniqueIndex("calendar_permission_bundles_calendarId_seedKey_idx")
      .on(table.calendarId, table.seedKey)
      .where(sql`${table.seedKey} is not null`),
  ]
);

export const calendarShares = sqliteTable(
  "calendar_shares",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    calendarId: text("calendar_id")
      .notNull()
      .references(() => calendars.id, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    // restrict, not cascade: deleting a bundle must never silently delete
    // shares — the app checks usage first and rejects deletion (see plan).
    bundleId: text("bundle_id")
      .notNull()
      .references(() => calendarPermissionBundles.id, {
        onDelete: "restrict",
      }),
    sharedBy: text("shared_by")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    createdAt: integer("created_at", { mode: "timestamp" })
      .notNull()
      .default(sql`CURRENT_TIMESTAMP`),
  },
  (table) => [
    index("calendar_shares_calendarId_idx").on(table.calendarId),
    index("calendar_shares_userId_idx").on(table.userId),
    index("calendar_shares_bundleId_idx").on(table.bundleId),
  ]
);

export const userCalendarSubscriptions = sqliteTable(
  "user_calendar_subscriptions",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    calendarId: text("calendar_id")
      .notNull()
      .references(() => calendars.id, { onDelete: "cascade" }),
    status: text("status", { enum: ["subscribed", "dismissed"] })
      .notNull()
      .default("subscribed"),
    source: text("source", { enum: ["guest", "shared"] })
      .notNull()
      .default("guest"),
    createdAt: integer("created_at", { mode: "timestamp" })
      .notNull()
      .default(sql`CURRENT_TIMESTAMP`),
    updatedAt: integer("updated_at", { mode: "timestamp" })
      .notNull()
      .default(sql`CURRENT_TIMESTAMP`)
      .$onUpdate(() => new Date()),
  },
  (table) => [
    index("user_calendar_subscriptions_userId_idx").on(table.userId),
    index("user_calendar_subscriptions_calendarId_idx").on(table.calendarId),
    index("user_calendar_subscriptions_status_idx").on(table.status),
  ]
);

export const userPreferences = sqliteTable("user_preferences", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  viewSettings: text("view_settings", {
    mode: "json",
  }).$type<PersonalViewSettings>(),
  updatedAt: integer("updated_at", { mode: "timestamp" })
    .notNull()
    .default(sql`CURRENT_TIMESTAMP`)
    .$onUpdate(() => new Date()),
});

// Single-row table (id is always "default") for instance-wide toggles.
export const systemSettings = sqliteTable("system_settings", {
  id: text("id").primaryKey().default("default"),
  updateCheckEnabled: integer("update_check_enabled", { mode: "boolean" })
    .notNull()
    .default(true),
  updateBannerVisibility: text("update_banner_visibility", {
    enum: ["all", "admins"],
  })
    .notNull()
    .default("all"),
  // Nullable: existing rows from before this column existed must fall back
  // to ALLOW_GUEST_ACCESS (see lib/system-settings.ts), not silently to
  // false -- a NOT NULL DEFAULT would force that on every upgrade.
  allowGuestAccess: integer("allow_guest_access", { mode: "boolean" }),
  // Nullable without default: telemetryEnabled null means "not decided yet",
  // and no instance id exists until telemetry is actually on.
  telemetryEnabled: integer("telemetry_enabled", { mode: "boolean" }),
  telemetryInstanceId: text("telemetry_instance_id"),
  telemetryConsentedSchema: integer("telemetry_consented_schema"),
  telemetryDecidedAt: integer("telemetry_decided_at", { mode: "timestamp" }),
  // Drives the daily send: the scheduler compares it against now instead of
  // counting 24h from server start, so restarts do not reset the rhythm.
  telemetryLastSentAt: integer("telemetry_last_sent_at", { mode: "timestamp" }),
  updatedAt: integer("updated_at", { mode: "timestamp" })
    .notNull()
    .default(sql`CURRENT_TIMESTAMP`)
    .$onUpdate(() => new Date()),
});

export const externalSyncs = sqliteTable("external_syncs", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  calendarId: text("calendar_id")
    .notNull()
    .references(() => calendars.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  syncType: text("sync_type").notNull().default("icloud"), // icloud, google, custom
  calendarUrl: text("calendar_url").notNull(),
  color: text("color").notNull().default("#3b82f6"),
  displayMode: text("display_mode").notNull().default("normal"),
  isHidden: integer("is_hidden", { mode: "boolean" }).notNull().default(false),
  hideFromStats: integer("hide_from_stats", { mode: "boolean" })
    .notNull()
    .default(false),
  autoSyncInterval: integer("auto_sync_interval").notNull().default(0), // 0 = manual, otherwise minutes
  isOneTimeImport: integer("is_one_time_import", { mode: "boolean" })
    .notNull()
    .default(false), // true for uploaded files (no sync), false for URLs (can sync)
  lastSyncedAt: integer("last_synced_at", { mode: "timestamp" }),
  createdAt: integer("created_at", { mode: "timestamp" })
    .notNull()
    .default(sql`CURRENT_TIMESTAMP`),
  updatedAt: integer("updated_at", { mode: "timestamp" })
    .notNull()
    .default(sql`CURRENT_TIMESTAMP`),
});

export const shifts = sqliteTable("shifts", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  calendarId: text("calendar_id")
    .notNull()
    .references(() => calendars.id, { onDelete: "cascade" }),
  presetId: text("preset_id").references(() => shiftPresets.id, {
    onDelete: "set null",
  }),
  date: integer("date", { mode: "timestamp" }).notNull(),
  startTime: text("start_time").notNull(),
  endTime: text("end_time").notNull(),
  title: text("title").notNull(),
  color: text("color").notNull().default("#3b82f6"),
  notes: text("notes"),
  isAllDay: integer("is_all_day", { mode: "boolean" }).notNull().default(false),
  isSecondary: integer("is_secondary", { mode: "boolean" })
    .notNull()
    .default(false),
  // Target headcount for shift signups; null = unlimited
  signupCapacity: integer("signup_capacity"),
  externalEventId: text("external_event_id"),
  externalSyncId: text("external_sync_id").references(() => externalSyncs.id, {
    onDelete: "cascade",
  }),
  syncedFromExternal: integer("synced_from_external", { mode: "boolean" })
    .notNull()
    .default(false),
  // null = no known creator (pre-migration data, anonymous guest, or the
  // creating user was later deleted) — counts as "own" for anyone with the
  // Own capability, see hasOwnedCapability().
  createdBy: text("created_by").references(() => user.id, {
    onDelete: "set null",
  }),
  createdAt: integer("created_at", { mode: "timestamp" })
    .notNull()
    .default(sql`CURRENT_TIMESTAMP`),
  updatedAt: integer("updated_at", { mode: "timestamp" })
    .notNull()
    .default(sql`CURRENT_TIMESTAMP`),
});

export const shiftPresets = sqliteTable("shift_presets", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  calendarId: text("calendar_id")
    .notNull()
    .references(() => calendars.id, { onDelete: "cascade" }),
  title: text("title").notNull(),
  startTime: text("start_time").notNull(),
  endTime: text("end_time").notNull(),
  color: text("color").notNull().default("#3b82f6"),
  notes: text("notes"),
  groupName: text("group_name"),
  isSecondary: integer("is_secondary", { mode: "boolean" })
    .notNull()
    .default(false),
  isAllDay: integer("is_all_day", { mode: "boolean" }).notNull().default(false),
  hideFromStats: integer("hide_from_stats", { mode: "boolean" })
    .notNull()
    .default(false),
  // Copied into signupCapacity on shifts created from this preset
  defaultSignupCapacity: integer("default_signup_capacity"),
  order: integer("order").notNull().default(0),
  // null = active. Archived presets can no longer create shifts, but shifts
  // already stamped from them stay untouched.
  archivedAt: integer("archived_at", { mode: "timestamp" }),
  // null = no known creator, see shifts.createdBy above.
  createdBy: text("created_by").references(() => user.id, {
    onDelete: "set null",
  }),
  createdAt: integer("created_at", { mode: "timestamp" })
    .notNull()
    .default(sql`CURRENT_TIMESTAMP`),
  updatedAt: integer("updated_at", { mode: "timestamp" })
    .notNull()
    .default(sql`CURRENT_TIMESTAMP`),
});

