export const calendarCustomFields = sqliteTable(
  "calendar_custom_fields",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    calendarId: text("calendar_id")
      .notNull()
      .references(() => calendars.id, { onDelete: "cascade" }),
    // Stable API identifier: `shift.customFields[key]`. Immutable once created,
    // because renaming it would break every consumer reading that key.
    key: text("key").notNull(),
    label: text("label").notNull(),
    type: text("type").notNull().$type<CustomFieldType>(),
    // Only set for type "select"; null for every other type.
    options: text("options", { mode: "json" }).$type<CustomFieldOption[]>(),
    required: integer("required", { mode: "boolean" }).notNull().default(false),
    showInCalendar: integer("show_in_calendar", { mode: "boolean" })
      .notNull()
      .default(false),
    order: integer("order").notNull().default(0),
    // null = no known creator, see shifts.createdBy above.
    createdBy: text("created_by").references(() => user.id, {
      onDelete: "set null",
    }),
    createdAt: integer("created_at", { mode: "timestamp" })
      .notNull()
      .default(sql`CURRENT_TIMESTAMP`),
    updatedAt: integer("updated_at", { mode: "timestamp" })
      .notNull()
      .default(sql`CURRENT_TIMESTAMP`)
      .$onUpdate(() => new Date()),
  },
  (table) => [
    index("calendar_custom_fields_calendarId_idx").on(table.calendarId),
    uniqueIndex("calendar_custom_fields_calendarId_key_idx").on(
      table.calendarId,
      table.key
    ),
  ]
);

